export const getPowerLevels = (room: Room): IPowerLevelsContent =>
    room?.currentState?.getStateEvents(EventType.RoomPowerLevels, "")?.getContent() || {};

export const useRoomPowerLevels = (cli: MatrixClient, room: Room): IPowerLevelsContent => {
    const [powerLevels, setPowerLevels] = useState<IPowerLevelsContent>(getPowerLevels(room));

    const update = useCallback(
        (ev?: MatrixEvent) => {
            if (!room) return;
            if (ev && ev.getType() !== EventType.RoomPowerLevels) return;
            setPowerLevels(getPowerLevels(room));
        },
        [room],
    );

    useTypedEventEmitter(cli, RoomStateEvent.Events, update);
    useEffect(() => {
        update();
        return () => {
            setPowerLevels({});
        };
    }, [update]);
    return powerLevels;
};

interface IBaseProps {
    member: RoomMember;
    startUpdating(): void;
    stopUpdating(): void;
}

type AdminActionLock = {
    isPending(member: RoomMember): boolean;
    run(member: RoomMember, action: () => Promise<void>, errorTitle: string): Promise<void>;
};

const AdminActionContext = React.createContext<AdminActionLock | null>(null);

function useAdminActionLock(): AdminActionLock {
    const active = useRef(new Set<string>());
    const [pending, setPending] = useState(new Set<string>());
    const keyFor = (member: RoomMember): string => `${member.roomId}\0${member.userId}`;

    return {
        isPending: (member) => pending.has(keyFor(member)),
        run: async (member, action, errorTitle) => {
            const key = keyFor(member);
            // The ref closes the gap before React commits the disabled state.
            if (active.current.has(key)) return;
            active.current.add(key);
            setPending(new Set(active.current));
            try {
                await action();
            } catch (err) {
                logger.error("Admin action failed: ", err);
                Modal.createDialog(ErrorDialog, {
                    title: errorTitle,
                    description: err instanceof Error ? err.message : _t("Operation failed"),
                });
            } finally {
                active.current.delete(key);
                setPending(new Set(active.current));
            }
        },
    };
}

export const RoomKickButton = ({
    room,
    member,
    startUpdating,
    stopUpdating,
}: Omit<IBaseRoomProps, "powerLevels">): JSX.Element | null => {
    const cli = useContext(MatrixClientContext);
    const localActionLock = useAdminActionLock();
    const actionLock = useContext(AdminActionContext) ?? localActionLock;

    // check if user can be kicked/disinvited
    if (member.membership !== "invite" && member.membership !== "join") return <></>;

    const onKick = (): Promise<void> =>
        actionLock.run(
            member,
            async () => {
                const commonProps = {
                    member,
                    action: room.isSpaceRoom()
                        ? member.membership === "invite"
                            ? _t("Disinvite from space")
                            : _t("Remove from space")
                        : member.membership === "invite"
                        ? _t("Disinvite from room")
                        : _t("Remove from room"),
                    title:
                        member.membership === "invite"
                            ? _t("Disinvite from %(roomName)s", { roomName: room.name })
                            : _t("Remove from %(roomName)s", { roomName: room.name }),
                    askReason: member.membership === "join",
                    danger: true,
                };

                let finished: Promise<[success?: boolean, reason?: string, rooms?: Room[]]>;

                if (room.isSpaceRoom()) {
                    ({ finished } = Modal.createDialog(
                        ConfirmSpaceUserActionDialog,
                        {
                            ...commonProps,
                            space: room,
                            spaceChildFilter: (child: Room) => {
                                // Return true if the target member is not banned and we have sufficient PL to ban them
                                const myMember = child.getMember(cli.credentials.userId || "");
                                const theirMember = child.getMember(member.userId);
                                return (
                                    !!myMember &&
                                    !!theirMember &&
                                    theirMember.membership === member.membership &&
                                    myMember.powerLevel > theirMember.powerLevel &&
                                    child.currentState.hasSufficientPowerLevelFor("kick", myMember.powerLevel)
                                );
                            },
                            allLabel: _t("Remove them from everything I'm able to"),
                            specificLabel: _t("Remove them from specific things I'm able to"),
                            warningMessage: _t("They'll still be able to access whatever you're not an admin of."),
                        },
                        "mx_ConfirmSpaceUserActionDialog_wrapper",
                    ));
                } else {
                    ({ finished } = Modal.createDialog(ConfirmUserActionDialog, commonProps));
                }

                const [proceed, reason, rooms = []] = await finished;
                if (!proceed) return;

                startUpdating();
                try {
                    await bulkSpaceBehaviour(room, rooms, (room) =>
                        cli.kick(room.roomId, member.userId, reason || undefined),
                    );
                    // Rely on the m.room.member event to update the UI.
                    logger.log("Kick success");
                } finally {
                    stopUpdating();
                }
            },
            _t("Failed to remove user"),
        );

    const kickLabel = room.isSpaceRoom()
        ? member.membership === "invite"
            ? _t("Disinvite from space")
            : _t("Remove from space")
        : member.membership === "invite"
        ? _t("Disinvite from room")
        : _t("Remove from room");

    return (
        <AccessibleButton
            kind="link"
            className="mx_UserInfo_field mx_UserInfo_destructive"
            onClick={onKick}
            disabled={actionLock.isPending(member)}
        >
            {kickLabel}
        </AccessibleButton>
    );
};

